#!/bin/bash
# usage: tok.sh <files...> > token stream
perl -0777 -pe '
  s{/\*.*?\*/}{}gs;
  s{//[^\n]*}{}g;
  s{\x27(?:[^\x27\\]|\\.)*\x27}{STR}gs;   # single-quoted strings
  s{\x22(?:[^\x22\\]|\\.)*\x22}{STR}gs;   # double-quoted strings
  s{\s+}{}g;
  s{([{}()<>[\];,:.!?&|=+\-*/%^~@#])}{\n$1\n}g;
' "$@" | grep -vE '^\s*$'
EOF
chmod +x /tmp/splitcheck/tok.sh
# Also strip part/part-of lines via sed first
mkdir -p /tmp/splitcheck/strip
strip_parts() { grep -hvE "^\s*part\s+('|of)" "$@"; }
check_tok() {
  local name="$1"; local mainfile="$2"; shift 2
  git show origin/main:$mainfile | grep -vE "^\s*part\s+('|of)" | /tmp/splitcheck/tok.sh > /tmp/splitcheck/tm.txt
  strip_parts "$@" | /tmp/splitcheck/tok.sh > /tmp/splitcheck/tn.txt
  local d=$(diff /tmp/splitcheck/tm.txt /tmp/splitcheck/tn.txt | wc -l)
  echo "=== $name: token-diff lines=$d  (main=$(wc -l < /tmp/splitcheck/tm.txt) new=$(wc -l < /tmp/splitcheck/tn.txt))"
  diff /tmp/splitcheck/tm.txt /tmp/splitcheck/tn.txt | head -40
}
